-- Generated by tools/write_source_queries.py from focus/data/datasets.py. Read-only; explicit projection (S05).
-- SQL-owned team inference output (S06 FOCUS_FN_TeamInference) for the latest COMPLETE source run.
SELECT CONVERT(varchar(40), ti.RunId) AS RUN_ID, ti.PersonKey AS PERSON_KEY, ti.InferredTeam AS INFERRED_TEAM,
 ti.WindowStartUtc AS WINDOW_START_UTC, ti.WindowEndUtc AS WINDOW_END_UTC, ti.EvidenceCount AS EVIDENCE_COUNT,
 ti.EffortMinutes AS EFFORT_MINUTES, ti.TopShare AS TOP_SHARE,
 JSON_VALUE(CONVERT(nvarchar(max), ti.EvidencePayload), '$.runner_up_team') AS RUNNER_UP_TEAM,
 TRY_CONVERT(int, JSON_VALUE(CONVERT(nvarchar(max), ti.EvidencePayload), '$.runner_up_count')) AS RUNNER_UP_COUNT,
 ti.IsTie AS IS_TIE, ti.Basis AS BASIS, ti.AlgorithmVersion AS ALGORITHM_VERSION,
 TRY_CONVERT(datetime2(6), JSON_VALUE(CONVERT(nvarchar(max), ti.EvidencePayload), '$.first_evidence_utc')) AS FIRST_EVIDENCE_UTC,
 TRY_CONVERT(datetime2(6), JSON_VALUE(CONVERT(nvarchar(max), ti.EvidencePayload), '$.last_evidence_utc')) AS LAST_EVIDENCE_UTC
FROM WEB_APP.FOCUS_FN_TeamInference ti
WHERE ti.RunId = (SELECT TOP 1 h.RunId FROM WEB_APP.FOCUS_FN_SourceHead h ORDER BY h.UpdatedAtUtc DESC);
